class _CmdlineVars:
    def __init__(self):
        self._store = {}
    def reset(self): self._store = {}
    def set(self, name, value): self._store[name] = value
    def get(self, name, default=None): return self._store.get(name, default)

cmdline_vars = _CmdlineVars()

